package cl.will.lanremote;
import android.app.*;import android.content.*;import android.media.projection.*;import android.os.*;
public class LanRemoteService extends Service {public static final String EXTRA_CODE="code",EXTRA_DATA="data",EXTRA_PORT="port";LanServer server;FrameStreamer fs;MediaProjection mp;int activePort=-1;
 public int onStartCommand(Intent i,int flags,int id){startForegroundNow();int port=i==null?Protocol.PORT:i.getIntExtra(EXTRA_PORT,Protocol.PORT);if(server==null||activePort!=port){if(server!=null)server.stop();server=new LanServer(port);activePort=port;server.start();if(fs!=null)server.setStreamer(fs);}Intent data=i==null?null:(Intent)i.getParcelableExtra(EXTRA_DATA);int code=i==null?Activity.RESULT_CANCELED:i.getIntExtra(EXTRA_CODE,Activity.RESULT_CANCELED);if(data!=null&&code==Activity.RESULT_OK){try{if(fs!=null)fs.stop();if(mp!=null)mp.stop();}catch(Throwable ignored){}MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);mp=m.getMediaProjection(code,data);fs=new FrameStreamer(this,mp,server);server.setStreamer(fs);fs.start();}return START_STICKY;}
 void startForegroundNow(){String ch="lanremote";if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(ch,"LAN Remote",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,ch):new Notification.Builder(this);startForeground(7,b.setContentTitle("LAN Remote").setContentText("Wi-Fi remote server active").setSmallIcon(android.R.drawable.stat_sys_upload).build());}
 public void onDestroy(){RemoteAccessibilityService.cursorVisible(false);if(fs!=null)fs.stop();if(server!=null)server.stop();if(mp!=null)mp.stop();super.onDestroy();}public android.os.IBinder onBind(Intent i){return null;}}
